import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {side, price, qty, seq}
    seq_counter = 0

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        seq_counter += 1
        if typ == 'limit' or typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                if sid not in book or book[sid]['qty'] <= 0 or book[sid]['price'] != sp:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                trade_qty = min(remaining, book[sid]['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] == 0:
                    heapq.heappop(sell_heap)
                    del book[sid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq_counter}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
        else:  # sell
            while remaining > 0 and buy_heap:
                negp, bseq, bid = buy_heap[0]
                bp = -negp
                if bid not in book or book[bid]['qty'] <= 0 or book[bid]['price'] != bp:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                trade_qty = min(remaining, book[bid]['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] == 0:
                    heapq.heappop(buy_heap)
                    del book[bid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq_counter}
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

